72	    /**
73	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
74	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
75	     * and a dotted domain (e.g. {@code not-an-email}).
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
78	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
79	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
80	
81	    /**
82	     * Disposable email domains that are not allowed for an owner. An email whose domain (the part
83	     * after the '@', compared case-insensitively) is listed here is rejected with 400 Bad Request.
84	     */
85	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
86	        "mailinator.com",
87	        "tempmail.com",
88	        "guerrillamail.com");
89	
90	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
91	    private static final String DEFAULT_COUNTRY_CODE = "61";
92	
93	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
94	    private static final int MAX_OWNERS_PER_CITY = 50;
95	
96	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
100	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
101	
102	    /** Fixed public-holiday calendar: a registration date landing on any of these is rolled forward past it. */
103	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
104	        LocalDate.of(2026, 1, 1),
105	        LocalDate.of(2026, 1, 26),
106	        LocalDate.of(2026, 4, 25),
107	        LocalDate.of(2026, 12, 25),
108	        LocalDate.of(2026, 12, 28));
109	
110	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
111	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
112	
113	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
114	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
115	
116	    /**
117	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
118	     * is listed here must carry exactly the required number of national digits, otherwise it is
119	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
120	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
121	     */
122	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
123	        "61", 9,
124	        "1", 10);
125	
126	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
127	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
128	        "ST", "STREET",
129	        "RD", "ROAD",
130	        "AVE", "AVENUE");
131	
132	    /** A well-formed postcode: exactly four digits. */
133	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
134	
135	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
136	    private static final Map<String, String> CITY_REGION = Map.of(
137	        "Sydney", "NSW",
138	        "Melbourne", "VIC",
139	        "Brisbane", "QLD");
140	
