142	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
143	        "NSW", new int[] {2000, 2099},
144	        "VIC", new int[] {3000, 3099},
145	        "QLD", new int[] {4000, 4099});
