148	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
149	
150	    /** Request header carrying the client-supplied idempotency key for a create. */
151	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
