205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
208	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
209	        // originally created owner with 200 instead of creating (and duplicate-checking) a new one.
210	        String idempotencyKey = currentIdempotencyKey();
211	        if (idempotencyKey != null) {
212	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
213	            if (existingId != null) {
214	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
215	                if (existingOwner != null) {
216	                    populateHouseholdSize(existingOwner);
217	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
218	                }
219	            }
220	        }
221	        List<String> missingFields = new ArrayList<>();
222	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
223	            missingFields.add("firstName");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
226	            missingFields.add("lastName");
227	        }
228	        // Normalize each supplied address form up front. The structured fields are preferred when
229	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
230	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
231	        // address). A whitespace-only value collapses to the empty string and counts as absent.
232	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
233	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
234	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
235	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
236	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
237	        if (!hasStructuredAddress && !hasFlatAddress) {
238	            missingFields.add("address");
239	        }
240	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
241	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
242	        String composedAddress;
243	        if (hasStructuredAddress) {
244	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
245	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
246	                : normalizedAddressLine1;
247	        } else {
248	            composedAddress = normalizedFlatAddress;
249	        }
250	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
251	            missingFields.add("city");
252	        }
253	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
254	            missingFields.add("telephone");
255	        }
256	        if (!missingFields.isEmpty()) {
257	            throw new InvalidRequestException(missingFields);
258	        }
259	        HttpHeaders headers = new HttpHeaders();
260	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
261	        // A newly created owner is never soft-deleted.
262	        owner.setDeleted(false);
263	        // Store (and later return) the normalized structured lines and the composed address. The
264	        // structured lines are kept only when the structured form was supplied; otherwise they are
265	        // cleared so the response reflects the flat form that was actually used.
266	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
267	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
268	            ? normalizedAddressLine2 : null);
269	        owner.setAddress(composedAddress);
270	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
271	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
272	        owner.setTelephone(normalizedTelephone);
273	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
274	        owner.setEmail(normalizeEmail(owner.getEmail()));
275	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
276	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
277	        validatePostcode(owner.getCity(), owner.getPostcode());
278	        // Reject a supplied registration date that lies in the future (later than the server's current
279	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
280	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
281	            throw new InvalidRequestException(List.of("registrationDate"));
282	        }
283	        // Default the (optional) registration date to the server's current date when none was supplied.
284	        if (owner.getRegistrationDate() == null) {
285	            owner.setRegistrationDate(LocalDate.now());
286	        }
287	        // The effective registration date must fall on a business day: when it lands on a Saturday,
288	        // Sunday or a listed public holiday (whether supplied or defaulted above), roll it forward to
289	        // the next non-holiday business day. Every value derived from the registration date below
290	        // (daily create-limit, membership number) uses this adjusted date.
291	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
292	        // Reject the request once the maximum number of owners for the owner's registration day has
293	        // been reached (100 or more owners already created on that date).
294	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
295	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
296	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
297	        }
298	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
299	        // owner's registration day at the moment this owner was created; otherwise clear it.
300	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
301	        // Reject the request when the owner's city has already reached its owner capacity.
302	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
303	            throw new CityCapacityException(owner.getCity());
304	        }
305	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
306	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
307	        // so any two owners with the same last name and postcode automatically resolve to the same
308	        // household without an explicit opt-in. It is assigned up front so it feeds duplicate
309	        // detection (the identity key below), the household-size read-back and household-duplicate
310	        // detection alike.
311	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
312	        owner.setHouseholdId(householdId);
313	        // Household-duplicate detection: because the household is keyed on (lastName, postcode), any
314	        // existing owner already carrying this householdId is a member of the same household, so this
315	        // create is a household duplicate. Reject it with 409 unless the caller opts in via
316	        // 'sharesHousehold', which now only bypasses this block (the household link already exists by
317	        // construction) and marks the owner as a declared household member.
318	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
319	            .filter(existing -> !existing.isDeleted())
320	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
321	        boolean declaredHouseholdMember = false;
322	        if (householdMemberExists) {
323	            if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
324	                declaredHouseholdMember = true;
325	            } else {
326	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
327	            }
328	        }
329	        // All duplicate detection is consolidated into this single derived identity key
330	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
331	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
332	        // telephone is part of the key, two members of the same household with different telephones
333	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
334	        String identityKey = owner.getIdentityKey();
335	        boolean identityCollision = this.clinicService.findAllOwners().stream()
336	            .filter(existing -> !existing.isDeleted())
337	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
338	        if (identityCollision) {
339	            throw new DuplicateIdentityException(identityKey);
340	        }
341	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
342	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
343	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
344	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
345	        // match, the one with the lowest id is chosen so the result is deterministic. A declared
346	        // household member is an intentional co-resident, not a suspected duplicate, so it is never
347	        // flagged (a create that reaches this point sharing a last name and postcode with an
348	        // existing owner is precisely a declared household member).
349	        Owner softMatch = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
350	        if (softMatch != null) {
351	            owner.setPossibleDuplicate(true);
352	            owner.setPossibleDuplicateOf(softMatch.getId());
353	        } else {
354	            owner.setPossibleDuplicate(false);
355	        }
356	        // Record how many existing owners already share this first name and last name
357	        // (compared case-insensitively) before this owner is created.
358	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
359	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
360	        owner.setCustomerCode(generateCustomerCode(owner));
361	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
362	        // digits of the fiscal year the registration date falls in (e.g. 'NSW-1A2B3C4D-M27').
363	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
364	        this.clinicService.saveOwner(owner);
365	        // Remember the created owner under the request's idempotency key so a later create repeating
366	        // the same key returns this owner instead of creating a duplicate.
367	        if (idempotencyKey != null) {
368	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
369	        }
370	        populateHouseholdSize(owner);
371	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
372	        // Emit an audit line carrying the new owner's id, customer code, registration date,
373	        // numeric membership level and membership number.
374	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
375	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
376	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
377	        headers.setLocation(UriComponentsBuilder.newInstance()
378	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
379	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
380	    }
381	
382	    /**
383	     * Return the current request's {@code Idempotency-Key} header value, or {@code null} when the
384	     * header is absent/blank or there is no bound servlet request.
385	     *
386	     * @return the trimmed idempotency key, or {@code null} when none was supplied
387	     */
388	    private String currentIdempotencyKey() {
389	        org.springframework.web.context.request.RequestAttributes attributes =
390	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
391	        if (attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes) {
392	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
393	            if (StringUtils.hasText(key)) {
394	                return key.trim();
395	            }
396	        }
397	        return null;
398	    }
