409	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
410	        currentOwner.setLastName(ownerFieldsDto.getLastName());
411	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
412	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
413	        this.clinicService.saveOwner(currentOwner);
414	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
415	    }
416	
417	    /**
418	     * Populate the owner's household size: the number of owners sharing this owner's
419	     * {@code householdId} (including the owner itself). An owner with no household is a household
420	     * of one.
421	     *
422	     * @param owner the owner whose household size should be computed and set
423	     */
424	    private void populateHouseholdSize(Owner owner) {
425	        String householdId = owner.getHouseholdId();
426	        if (!StringUtils.hasText(householdId)) {
427	            owner.setHouseholdSize(1);
428	            return;
429	        }
430	        int size = (int) this.clinicService.findAllOwners().stream()
431	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
432	            .count();
433	        owner.setHouseholdSize(size);
434	    }
435	
436	    /**
437	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
438	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
439	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
440	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
441	     * longer any per-city sequence number.
442	     *
443	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
444	     * @return the generated (collision-free) customer code
445	     */
446	    private String generateCustomerCode(Owner owner) {
447	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
448	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
449	        String baseCode = region + "-" + hash8;
450	        return deduplicateCustomerCode(baseCode);
451	    }
452	
453	    /**
454	     * Return a customer code that does not collide with any existing owner's customer code. When the
455	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
456	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
457	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
458	     * persisted, so it never counts as a collision with itself.
459	     *
460	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
461	     * @return the de-duplicated customer code
462	     */
463	    private String deduplicateCustomerCode(String baseCode) {
464	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
465	            .map(Owner::getCustomerCode)
466	            .filter(java.util.Objects::nonNull)
467	            .collect(java.util.stream.Collectors.toSet());
468	        if (!existingCodes.contains(baseCode)) {
469	            return baseCode;
470	        }
471	        int n = 2;
472	        String candidate = baseCode + "-" + n;
473	        while (existingCodes.contains(candidate)) {
474	            n++;
475	            candidate = baseCode + "-" + n;
476	        }
477	        return candidate;
478	    }
479	
480	    /**
481	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
482	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
483	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
484	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
485	     * known region.
486	     *
487	     * @param postcode the owner's postcode, may be {@code null}
488	     * @param city     the owner's city
489	     * @return the derived region code
490	     */
491	    private String deriveRegion(String postcode, String city) {
492	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
493	            int value = Integer.parseInt(postcode);
494	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
495	                int[] range = entry.getValue();
496	                if (value >= range[0] && value <= range[1]) {
497	                    return entry.getKey();
498	                }
499	            }
500	        }
501	        String region = CITY_REGION.get(city);
502	        return region != null ? region : "UNKNOWN";
503	    }
