505	    /**
506	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
507	     * bytes of {@code input}.
508	     *
509	     * @param input  the value to digest
510	     * @param length the number of leading hex characters to return
511	     * @return the truncated upper-case hex digest
512	     */
513	    private String shortSha256Hex(String input, int length) {
514	        try {
515	            byte[] digest = MessageDigest.getInstance("SHA-256")
516	                .digest(input.getBytes(StandardCharsets.UTF_8));
517	            StringBuilder sb = new StringBuilder(digest.length * 2);
518	            for (byte b : digest) {
519	                sb.append(String.format("%02x", b));
520	            }
521	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
522	        } catch (java.security.NoSuchAlgorithmException e) {
523	            throw new IllegalStateException("SHA-256 not available", e);
524	        }
525	    }
