527	    /**
528	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
529	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
530	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
531	     * date that is stored, returned and used for every value derived from it.
532	     *
533	     * @param date the effective registration date (supplied or defaulted)
534	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
535	     */
536	    private LocalDate rollToBusinessDay(LocalDate date) {
537	        while (!isBusinessDay(date)) {
538	            date = date.plusDays(1);
539	        }
540	        return date;
541	    }
542	
543	    /**
544	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
545	     *
546	     * @param date the date to test
547	     * @return {@code true} when the date is a non-holiday weekday
548	     */
549	    private boolean isBusinessDay(LocalDate date) {
550	        DayOfWeek dayOfWeek = date.getDayOfWeek();
551	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
552	            return false;
553	        }
554	        return !PUBLIC_HOLIDAYS.contains(date);
555	    }
