557	    /**
558	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
559	     * last two digits of the fiscal year that the (business-day-adjusted) {@code registrationDate}
560	     * falls in (e.g. {@code SYD-SMI-0007-M27} for a registration in FY27).
561	     *
562	     * @param customerCode     the owner's already-assigned customer code
563	     * @param registrationDate the owner's business-day-adjusted registration date
564	     * @return the generated membership number
565	     */
566	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
567	        String yy = String.format("%02d", fiscalYear(registrationDate) % 100);
568	        return String.format("%s-M%s", customerCode, yy);
569	    }
