653	    /**
654	     * Generate the deterministic household identifier for the given last name and postcode. The value
655	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
656	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
657	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
658	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
659	     *
660	     * @param lastName the owner's last name
661	     * @param postcode the owner's postcode, may be {@code null}
662	     * @return the deterministic household identifier
663	     */
664	    private String generateHouseholdId(String lastName, String postcode) {
665	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
666	        return shortSha256Hex(key, 12);
667	    }
