62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
