80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
