117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
